{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.anveshan_flipkart_order_fulfilment_fact_items; CREATE TABLE public.anveshan_flipkart_order_fulfilment_fact_items AS WITH ranked_data AS ( SELECT CAST(order_date AS TIMESTAMP) AS order_date, CAST(NULLIF(REPLACE(order_approval_date, \'\"\', \'\'), \'\') AS TIMESTAMP) AS order_approval_date, REPLACE(REPLACE(sku, \'\"\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, CAST(NULLIF(order_cancellation_date, \'\') AS TIMESTAMP) AS cancellation_date, REPLACE(cancellation_reason, \'_\', \' \') AS cancellation_reason, CAST(NULLIF(order_ready_for_dispatch_on_date, \'\') AS TIMESTAMP) AS order_ready_for_dispatch_on_date, CAST(NULLIF(dispatch_after_date, \'\') AS TIMESTAMP) AS manifest_date, CAST(NULLIF(dispatch_by_date, \'\') AS TIMESTAMP) AS dispatch_date, CASE WHEN deliver_by_date IN (\'N\', \'\') THEN NULL ELSE CAST(deliver_by_date AS DATE) END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%COD%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, CAST(NULLIF(order_return_approval_date, \'\') AS TIMESTAMP) AS return_approval_date, CAST(NULLIF(order_service_completion_date, \'\') AS TIMESTAMP) AS order_service_completion_date, return_id, REPLACE(return_reason, \'_\', \' \') AS return_reason, REPLACE(return_sub_reason, \'_\', \' \') AS return_sub_reason, REPLACE(order_item_id, \'OI:\', \'\') AS order_item_id, REPLACE(product_title, \'\"\', \'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status, \'_\', \' \') AS order_item_status, REPLACE(delivery_tracking_id, \'DTr:\', \'\') AS fk_awb, REPLACE(REPLACE(pickup_logistics_partner, \'-cod\', \'\'), \'-prepaid\', \'\') AS courier, ROW_NUMBER() OVER (PARTITION BY order_id, order_item_id ORDER BY return_approval_date DESC) as rn FROM public.anweshan_fk_orders ) SELECT order_date, order_approval_date, sku, reference_code, order_id, cancellation_date, cancellation_reason, order_ready_for_dispatch_on_date, manifest_date, dispatch_date, delivery_date, payment_mode, return_approval_date, order_service_completion_date, return_id, return_reason, return_sub_reason, order_item_id, product_name, fulfilment_type, fulfilment_source, order_item_status, fk_awb, courier FROM ranked_data WHERE rn = 1; DROP TABLE IF EXISTS public.flipkart_Seller_anveshan_sales_flattened; CREATE TABLE public.flipkart_Seller_anveshan_sales_flattened AS WITH flattened_ranked AS ( SELECT JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Customer\'\'s Billing State\') AS Customer_Billing_State, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'CGST Amount\') AS CGST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Customer\'\'s Delivery State\') AS Customer_Delivery_State, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'CST Amount\') AS CST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Total TCS Deducted\') AS Total_TCS_Deducted, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Product Title/Description\') AS Product_Title_Description, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Price before discount\') AS Price_before_discount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Price after discount (Price before discount-Total discount)\') AS Price_after_discount__Price_before_discount_Total_discount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS IGST Rate\') AS TCS_IGST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Warehouse ID\') AS Warehouse_ID, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TDS Rate\') AS TDS_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Shipping Charges\') AS Shipping_Charges, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS CGST Rate\') AS TCS_CGST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Type of tax\') AS Type_of_tax, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS IGST Amount\') AS TCS_IGST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Buyer Invoice Date\') AS Buyer_Invoice_Date, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Is Shopsy Order?\') AS Is_Shopsy_Order, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Seller Share\') AS Seller_Share, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Taxable Value (Final Invoice Amount -Taxes)\') AS Taxable_Value__Final_Invoice_Amount_Taxes, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'HSN Code\') AS HSN_Code, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Luxury Cess Amount\') AS Luxury_Cess_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'FSN\') AS FSN, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Customer\'\'s Billing Pincode\') AS Customer_Billing_Pincode, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order ID\') AS Order_ID, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Fulfilment Type\') AS Fulfilment_Type, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Total Discount\') AS Total_Discount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Usual Price\') AS Usual_Price, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Event Type\') AS Event_Type, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'IGST Amount\') AS IGST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'CGST Rate\') AS CGST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'VAT Amount\') AS VAT_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS CGST Amount\') AS TCS_CGST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'IRN\') AS IRN, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Buyer Invoice Amount\') AS Buyer_Invoice_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Shipped From (State)\') AS Order_Shipped_From__State, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Bank Offer Share\') AS Bank_Offer_Share, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Business Name\') AS Business_Name, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Customer\'\'s Delivery Pincode\') AS Customer_Delivery_Pincode, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Item Quantity\') AS Item_Quantity, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Beneficiary Name\') AS Beneficiary_Name, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'SGST Rate (or UTGST as applicable)\') AS SGST_Rate__or_UTGST_as_applicable, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Date\') AS Order_Date, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Buyer Invoice ID\') AS Buyer_Invoice_ID, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Business GST Number\') AS Business_GST_Number, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'IGST Rate\') AS IGST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Final Invoice Amount (Price after discount+Shipping Charges)\') AS Final_Invoice_Amount__Price_after_discount_Shipping_Charges, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS SGST Amount\') AS TCS_SGST_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'SGST Amount (Or UTGST as applicable)\') AS SGST_Amount__Or_UTGST_as_applicable, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Item ID\') AS Order_Item_ID, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'CST Rate\') AS CST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Luxury Cess Rate\') AS Luxury_Cess_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'IMEI\') AS IMEI, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Type\') AS Order_Type, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'VAT Rate\') AS VAT_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TCS SGST Rate\') AS TCS_SGST_Rate, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Seller GSTIN\') AS Seller_GSTIN, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Approval Date\') AS Order_Approval_Date, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'TDS Amount\') AS TDS_Amount, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'SKU\') AS SKU, JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Event Sub Type\') AS Event_Sub_Type, DENSE_RANK() OVER( PARTITION BY JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order ID\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Order Item ID\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Event Type\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'Event Sub Type\') ORDER BY DATE_TRUNC(\'second\', _airbyte_emitted_at) DESC ) AS rn FROM public._airbyte_raw_anweshan_fk_sales ) SELECT Customer_Billing_State, CGST_Amount, Customer_Delivery_State, CST_Amount, Total_TCS_Deducted, Product_Title_Description, Price_before_discount, Price_after_discount__Price_before_discount_Total_discount, TCS_IGST_Rate, Warehouse_ID, TDS_Rate, Shipping_Charges, TCS_CGST_Rate, Type_of_tax, TCS_IGST_Amount, Buyer_Invoice_Date, Is_Shopsy_Order, Seller_Share, Taxable_Value__Final_Invoice_Amount_Taxes, HSN_Code, Luxury_Cess_Amount, FSN, Customer_Billing_Pincode, Order_ID, Fulfilment_Type, Total_Discount, Usual_Price, Event_Type, IGST_Amount, CGST_Rate, VAT_Amount, TCS_CGST_Amount, IRN, Buyer_Invoice_Amount, Order_Shipped_From__State, Bank_Offer_Share, Business_Name, Customer_Delivery_Pincode, Item_Quantity, Beneficiary_Name, SGST_Rate__or_UTGST_as_applicable, Order_Date, Buyer_Invoice_ID, Business_GST_Number, IGST_Rate, Final_Invoice_Amount__Price_after_discount_Shipping_Charges, TCS_SGST_Amount, SGST_Amount__Or_UTGST_as_applicable, Order_Item_ID, CST_Rate, Luxury_Cess_Rate, IMEI, Order_Type, VAT_Rate, TCS_SGST_Rate, Seller_GSTIN, Order_Approval_Date, TDS_Amount, SKU, Event_Sub_Type FROM flattened_ranked WHERE rn = 1; DROP TABLE IF EXISTS public.anveshan_flipkart_fact_items; CREATE TABLE public.anveshan_flipkart_fact_items AS SELECT CASE WHEN s.Fulfilment_Type = \'NON_FBF\' THEN \'Flipkart NON-FBF\' ELSE \'Flipkart FBF\' END AS shop_name, s.order_id, s.order_id AS order_name, CAST(NULL AS VARCHAR) AS customer_id, CAST(NULL AS VARCHAR) AS phone, HSN_Code, s.order_type AS payment_type, CAST(NULL AS VARCHAR) AS tags, s.Order_Item_ID AS line_item_id, CAST(REPLACE(REPLACE(s.sku, \'\"\', \'\'), \'SKU:\', \'\') AS VARCHAR) AS SKU, REPLACE(s.FSN, \'\"\', \'\') AS product_id, CASE WHEN s.Event_Type = \'Return\' THEN 1 ELSE 0 END AS is_refund, CAST(pin.city AS VARCHAR) AS city, UPPER(COALESCE(pin.state,CASE WHEN s.Customer_Delivery_State = \'-\' THEN (CASE WHEN s.Customer_Delivery_State = \'-\' THEN NULL ELSE s.Customer_Billing_State END) ELSE s.Customer_Delivery_State END)) AS state, CASE WHEN s.Customer_Delivery_Pincode = \'-\' THEN (CASE WHEN s.Customer_Billing_Pincode = \'-\' THEN NULL ELSE s.Customer_billing_Pincode END) ELSE s.Customer_Delivery_Pincode END AS pincode, REPLACE(Product_Title_Description, \'\"\', \'\') AS PRODUCT_NAME, upper(coalesce(p.category,p1.category)) AS category, upper(coalesce(p.product_name,p1.product_name)) AS product_name_final, coalesce(p.tax_rate,p1.tax_rate) AS pm_tax_rate, coalesce(p.cogs,p1.cogs) AS cogs, upper(coalesce(p.commonsku,p1.commonsku)) AS commonsku, CASE WHEN s.order_date = \'-\' then null else CAST(s.order_date AS timestamp) end AS order_date, CAST(LEFT(s.Buyer_Invoice_Date, 10) AS DATE) AS invoice_Date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, CAST(tds_rate AS FLOAT) AS tds_rate, CAST(VAT_Rate AS FLOAT) AS VAT_Rate, CAST(CGST_Rate AS FLOAT) AS CGST_Rate, CAST(IGST_Rate AS FLOAT) AS IGST_Rate, CAST(CST_Amount AS FLOAT) AS CST_Amount, CASE WHEN TDS_Amount <> \'NA\' THEN CAST(TDS_Amount AS FLOAT) ELSE NULL END AS TDS_Amount, CAST(VAT_Amount AS FLOAT) AS VAT_Amount, CAST(CGST_Amount AS FLOAT) AS CGST_Amount, CAST(IGST_Amount AS FLOAT) AS IGST_Amount, CAST(Type_of_tax AS FLOAT) AS Type_of_tax, CASE WHEN Usual_Price <> \'NA\' AND Usual_Price <> \'false\' THEN CAST(Usual_Price AS FLOAT) ELSE NULL END AS Usual_Price, Seller_GSTIN, ABS(COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) AS line_item_sales, ABS(COALESCE(CAST(Shipping_Charges AS FLOAT), 0)) AS shipping_price, ABS(COALESCE(CAST(Item_Quantity AS FLOAT), 0)) AS quantity, ABS(COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)) AS tax, ABS( COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0) / NULLIF((COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0) + COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)), 0) ) AS overall_tax_rate, ABS(COALESCE(CAST(Total_Discount AS FLOAT), 0)) AS discount, ( ABS(COALESCE(CAST(Total_Discount AS FLOAT), 0)) / NULLIF((1 - (ABS(COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)) / NULLIF((ABS(COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)) + ABS(COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0))), 0))), 0) ) AS discount_before_tax, ( ABS(COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) - (ABS(COALESCE(CAST(Total_Discount AS FLOAT), 0)) / NULLIF((1 - (ABS(COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)) / NULLIF((ABS(COALESCE(CAST(Total_TCS_Deducted AS FLOAT), 0)) + ABS(COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0))), 0))), 0)) ) AS gross_sales_before_tax, ABS(COALESCE(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) AS total_sales, \'Flipkart Order\' AS Order_Channel, Beneficiary_Name AS name, CAST(NULL AS VARCHAR) AS email, Order_Shipped_From__State AS Order_Shipped_From_State, Warehouse_ID, Business_Name, f.courier, f.fk_awb FROM ( SELECT * FROM public.flipkart_Seller_anveshan_sales_flattened WHERE LOWER(Event_Sub_Type) like \'%sale%\' ) s LEFT JOIN public.anveshan_flipkart_order_fulfilment_fact_items f ON f.order_id = s.order_id AND f.order_item_id = s.order_item_id LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, flipkart_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY flipkart_sku ORDER BY LENGTH(COALESCE(flipkart_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON LOWER(CAST(REPLACE(REPLACE(REPLACE(s.sku,\'\"\',\'\'),\'SKU:\',\'\'),\'SH \',\'\') AS VARCHAR)) = LOWER(p.marketplace_sku) LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, flipkart_fsn as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY flipkart_fsn ORDER BY LENGTH(COALESCE(flipkart_fsn, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p1 ON LOWER(REPLACE(s.FSN,\'\"\',\'\')) = LOWER(p1.marketplace_sku) left join (select * from (select trim(upper(\"delivery city\")) as city, trim(upper(\"delivery state\")) as state, trim(\"delivery pincode\") as pincode, row_number() over (partition by pincode order by 1) as rw from public.anveshan_location_mapping) where rw=1 ) pin on replace(pin.pincode,\' \',\'\') = cast(s.customer_delivery_pincode as varchar);",
                    "transaction": true
                }
            ) }}
